Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis ICok : aicpt_ok L ar IL SCFG HI.
Hypothesis ILY : as0_icpt_layout IL.
Let LYa := PMA.ly_as0 L C LY.

(* [comment removed for export] *)
Definition cxsgetn_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r ois dst : Z) (str : PM.vstr) (sm : PM.strm),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> PMSPA.entryA PeCLayoutA.CADDR_A L ar R M sp r 2 ->
    PMSPA.ffroomA 2 FF LK -> PMSPA.ffrsA FF sp ->
    getr R 10%bv = Z_to_bv 64 (ois + 16) -> getr R 11%bv = Z_to_bv 64 dst -> getr R 12%bv = Z_to_bv 64 PM.CHUNK ->
    PMSPA.aobjA FF ois 272 -> ois mod 8 = 0 ->
    PM.iss_at RSEGS PeCLayoutA.CADDR_A PMSPA.accA M ois str sm -> PMSTA.base_okA RSEGS PeCLayoutA.CADDR_A M -> incl (PM.vs_own str) LB ->
    (exists B m, In (B, m) LB /\ B <= dst /\ dst + PM.CHUNK <= B + m) -> PMSPA.accA M dst PM.CHUNK ->
    (dst + PM.CHUNK <= PM.sm_g sm \/ PM.sm_eg sm <= dst) ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (c : Z),
        regs_preserved R R' -> getr R' 10%bv = Z_to_bv 64 c -> c = Z.min PM.CHUNK (PM.sm_eg sm - PM.sm_g sm) ->
        PM.iss_at RSEGS PeCLayoutA.CADDR_A PMSPA.accA M' ois str (PM.STRM (PM.sm_g sm + c) (PM.sm_eg sm) (PM.sm_st sm)) ->
        L5.defined M' dst c ->
        (forall l, Z.of_nat (length l) <= c -> L5.bytes_at RSEGS M (PM.sm_g sm) l -> L5.bytes_at RSEGS M' dst l) ->
        L5CA.ahpres L ar LB FF sp (PMSPA.pm_scr 2) [(ois + 40, 8); (dst, PM.CHUNK)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI LB FF LK' cr Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R (pa_xsgetn PeCLayoutA.CADDR_A) M model) K.

